60	    public async Task<CourseLessonsResponse?> GetCourseLessonsAsync(string courseKey)
61	    {
62	        var course = await db.Courses
63	            .Where(c => c.CourseKey == courseKey)
64	            .FirstOrDefaultAsync()
65	            ?? throw new KeyNotFoundException($"Course not found: {courseKey}");
66	
67	        var rawLessons = await db.Lessons
68	            .Where(l => l.CourseKey == courseKey)
69	            .OrderBy(l => l.WeekNumber)
70	            .Select(l => new { l.LessonId, l.WeekNumber, l.LessonDate, l.Topic, l.UpdatedAt })
71	            .ToListAsync();
72	
73	        var lessonIds = rawLessons.Select(l => l.LessonId).ToList();
74	        var aiResults = await db.AiResults
75	            .Where(r => lessonIds.Contains(r.LessonId))
76	            .Select(r => new { r.LessonId, r.IsScreenshotGenerated, r.UpdatedAt })
77	            .ToDictionaryAsync(r => r.LessonId);
78	
79	        var lessons = rawLessons.Select(l =>
80	        {
81	            var status = LessonEnum.LessonStatus.pending;
82	            string? lastUpdatedAt = null;
83	
84	            if (aiResults.TryGetValue(l.LessonId, out var ai))
85	            {
86	                status = ai.IsScreenshotGenerated ? LessonEnum.LessonStatus.completed : LessonEnum.LessonStatus.analyzing;
87	                lastUpdatedAt = ai.IsScreenshotGenerated ? ai.UpdatedAt.ToString("o") : null;
88	            }
89	
90	            return new LessonSummaryDto(
91	                LessonId: l.LessonId,
92	                WeekNumber: l.WeekNumber,
93	                LessonDate: l.LessonDate.ToString("yyyy-MM-dd"),
94	                Topic: l.Topic,
95	                Status: status.ToString(),
96	                LastUpdatedAt: lastUpdatedAt
97	            );
98	        }).ToList();
99	
100	        var schedules = course.SchedulesJson is null
101	            ? []
102	            : JsonSerializer.Deserialize<List<CourseScheduleDto>>(course.SchedulesJson, _caseInsensitive) ?? [];
103	
104	        return new CourseLessonsResponse(
105	            CourseId: course.CourseId,
106	            CourseName: course.Name,
107	            CourseSection: course.Section ?? "",
108	            CourseKey: courseKey,
109	            CourseSchedule: schedules,
110	            MaxCapacity: course.TotalStudentQuota,
111	            EnrolledCount: 0,
112	            Lessons: lessons
113	        );
114	    }
